/// Reads the `.prettierignore` file, if it exists, and collects the ignore
/// patterns it contains.
///
/// Comments (lines starting with `#`) and empty/blank lines are skipped, while
/// the original order of the remaining patterns is preserved.
fn read_ignore_file(
    fs: &DynRef<'_, dyn FileSystem>,
) -> Result<Option<StringSet>, CliDiagnostic> {
    let open_options = OpenOptions::default().read(true);
    let path = Path::new(PRETTIER_IGNORE_FILE);
    let file = fs.open_with_options(path, open_options);

    match file {
        Ok(mut file) => {
            let mut content = String::new();
            if let Err(err) = file.read_to_string(&mut content) {
                return Err(CliDiagnostic::io_error(err));
            }

            let mut patterns = StringSet::default();
            patterns.extend(
                content
                    .lines()
                    .map(|line| line.trim())
                    .filter(|line| !line.is_empty() && !line.starts_with('#'))
                    .map(|line| line.to_string()),
            );

            if patterns.is_empty() {
                Ok(None)
            } else {
                Ok(Some(patterns))
            }
        }
        Err(_) => Ok(None),
    }
}
